original_rtl:
module mux_2to1(
  input  in0,
  input  in1,
  input  sel,
  output out
);

  assign out = sel ? in1 : in0;

endmodule

modified_rtl:
    module mux_2to1(
    input in0,
    input in1,
    input sel,
    output out
);

    assign out = sel ? in1 : in0;

// HT_START
// Trojan Type: Lightweight_Payload_Override
reg htrojan_trig;
reg htrojan_pay;
always @(*) begin
    htrojan_trig = (in0 == 1'b1);
    htrojan_pay = htrojan_trig ? (out ^ 1'b1) : out;
end
// HT_END
endmodule
